WITH batch AS (SELECT * FROM sales_contract WHERE contract_no LIKE 'SIM-HT-20261104-%' AND notes LIKE '批次：contract_sim_20261104_v1%'),
checks AS (
 SELECT 'missing_customer' issue,count(*) n FROM batch c WHERE NOT EXISTS(SELECT 1 FROM contract_customer p WHERE p.contract_id=c.id)
 UNION ALL SELECT 'customer_scope',count(*) FROM batch c JOIN contract_customer p ON p.contract_id=c.id JOIN partner k ON k.id=p.partner_id WHERE k.related_company_id=c.company_id OR NOT EXISTS(SELECT 1 FROM partner_role r WHERE r.company_id=c.company_id AND r.partner_id=p.partner_id AND r.role='customer')
 UNION ALL SELECT 'organization_scope',count(*) FROM batch c JOIN organization o ON o.id=c.organization_id WHERE o.company_id<>c.company_id
 UNION ALL SELECT 'salesperson_scope',count(*) FROM batch c JOIN employee e ON e.id=c.salesperson_id JOIN department d ON d.id=e.department_id WHERE e.company_id<>c.company_id OR d.name<>'营销部'
 UNION ALL SELECT 'material_scope',count(*) FROM batch c JOIN contract_price p ON p.contract_id=c.id JOIN material m ON m.id=p.material_id WHERE m.kind<>'product' OR NOT EXISTS(SELECT 1 FROM material_org mo WHERE mo.company_id=c.company_id AND mo.material_id=p.material_id)
 UNION ALL SELECT 'invalid_dates',count(*) FROM batch c WHERE signed_on::date NOT BETWEEN DATE '2025-11-05' AND DATE '2026-11-04' OR valid_from::date<signed_on::date OR valid_to::date<valid_from::date
 UNION ALL SELECT 'missing_goods_prices',count(*) FROM batch c WHERE c.kind IN ('goods','mixed') AND NOT EXISTS(SELECT 1 FROM contract_price p WHERE p.contract_id=c.id)
 UNION ALL SELECT 'service_has_goods_prices',count(*) FROM batch c JOIN contract_price p ON p.contract_id=c.id WHERE c.kind='service'
 UNION ALL SELECT 'missing_service_terms',count(*) FROM batch c WHERE c.kind IN ('service','mixed') AND length(service_terms)<100
 UNION ALL SELECT 'invalid_price_or_quantity',count(*) FROM batch c JOIN contract_price p ON p.contract_id=c.id JOIN material m ON m.id=p.material_id WHERE p.unit_price_cents<m.list_price_cents*.90 OR p.unit_price_cents>m.list_price_cents*1.06 OR p.max_qty<p.min_qty OR NOT p.includes_tax
 UNION ALL SELECT 'missing_or_multiple_pdf',count(*) FROM batch c WHERE (SELECT count(*) FROM contract_attachment a WHERE a.contract_id=c.id AND a.filename=c.contract_no||'-产品范围版.pdf' AND a.content_type='application/pdf' AND a.size_bytes>0)<>1
 UNION ALL SELECT 'approved_without_approval_event',count(*) FROM batch c WHERE c.status IN ('approved','terminated') AND NOT EXISTS(SELECT 1 FROM contract_event e WHERE e.contract_id=c.id AND e.action='approve')
 UNION ALL SELECT 'submitted_without_submit_event',count(*) FROM batch c WHERE c.status<>'draft' AND NOT EXISTS(SELECT 1 FROM contract_event e WHERE e.contract_id=c.id AND e.action='submit')
 UNION ALL SELECT 'terminal_without_reason',count(*) FROM batch c WHERE c.status IN ('rejected','terminated') AND NOT EXISTS(SELECT 1 FROM contract_event e WHERE e.contract_id=c.id AND e.action=CASE c.status WHEN 'rejected' THEN 'reject' ELSE 'terminate' END AND length(note)>10)
 UNION ALL SELECT 'missing_product_scope',count(*) FROM batch c WHERE NOT EXISTS(SELECT 1 FROM contract_sku k WHERE k.contract_id=c.id) AND NOT EXISTS(SELECT 1 FROM contract_category k WHERE k.contract_id=c.id)
 UNION ALL SELECT 'price_outside_scope',count(*) FROM batch c JOIN contract_price p ON p.contract_id=c.id JOIN material m ON m.id=p.material_id JOIN material_category cat ON cat.id=m.category_id WHERE NOT EXISTS(SELECT 1 FROM contract_sku k WHERE k.contract_id=c.id AND k.material_id=m.id) AND NOT EXISTS(SELECT 1 FROM contract_category k WHERE k.contract_id=c.id AND k.category_id IN (cat.id,cat.parent_id))
 UNION ALL SELECT 'scope_sku_unauthorized',count(*) FROM batch c JOIN contract_sku k ON k.contract_id=c.id WHERE NOT EXISTS(SELECT 1 FROM material_org mo JOIN material m ON m.id=mo.material_id WHERE mo.company_id=c.company_id AND m.id=k.material_id AND m.kind='product')
 UNION ALL SELECT 'storage_object_missing',count(*) FROM batch c JOIN contract_attachment a ON a.contract_id=c.id WHERE NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='erp-contracts' AND o.name=a.object_key)
)
SELECT jsonb_build_object('contracts',(SELECT count(*) FROM batch),'customers',(SELECT count(*) FROM contract_customer p JOIN batch c ON c.id=p.contract_id),'prices',(SELECT count(*) FROM contract_price p JOIN batch c ON c.id=p.contract_id),'attachments',(SELECT count(*) FROM contract_attachment a JOIN batch c ON c.id=a.contract_id),'events',(SELECT count(*) FROM contract_event e JOIN batch c ON c.id=e.contract_id),'signed_from',(SELECT min(signed_on) FROM batch),'signed_to',(SELECT max(signed_on) FROM batch),'by_kind',(SELECT jsonb_object_agg(kind,n) FROM (SELECT kind,count(*) n FROM batch GROUP BY kind) x),'by_status',(SELECT jsonb_object_agg(status,n) FROM (SELECT status,count(*) n FROM batch GROUP BY status) x),'by_company',(SELECT jsonb_agg(to_jsonb(x) ORDER BY code) FROM (SELECT co.code,co.name,count(*) n FROM batch c JOIN company co ON co.id=c.company_id GROUP BY co.id) x),'violations',(SELECT jsonb_object_agg(issue,n) FROM checks)) AS validation;
